{
  "packet_id": "H6-T04-3",
  "claim_id": "C012",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C012.component",
    "value": "Evidence gathering should seek observations against each explanation as well as observations supporting it.",
    "scope": "Each retained candidate explanation.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping explicitly requires seeking evidence both against and for each explanation."
    }
  },
  "signal_basis": {
    "component_id": "C012.signal_basis",
    "value": "Observations can discriminate among competing explanations or remain compatible with several; accumulating corroborating and contradictory evidence informs their reprioritization.",
    "scope": "Retained explanations of onboarding delay or drop-off, bounded by observed customer types and follow-up.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "CONTEXT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P037",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish discrimination, ambiguous signals, revision using corroboration and contradiction, and the generalization boundary."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C012.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to license this bounded evidence-seeking requirement."
    }
  },
  "rationale": "Comparing explanations through evidence that supports or contradicts them licenses seeking both kinds of observation for each candidate. The claim prescribes an appropriate inquiry procedure without asserting that any particular explanation is established.",
  "uncertainty": "The requirement does not guarantee that discriminating evidence exists or that the candidate set is complete.",
  "anomalies": []
}
